// MARK: - Chinese review list seed

/// Chinese vocabulary shown in the second review list on the Home screen.
///
/// Stored as one tab-separated row per word inside a raw string literal
/// (日本語 / 中国語 / ピンイン / 会話頻度 1-5 / よく使う用例) — far more compact
/// than thousands of initialiser calls, and parsed once on first access.
enum ChineseSeed {
    static let words: [ChineseWord] = parse(raw)

    private static func parse(_ text: String) -> [ChineseWord] {
        var result: [ChineseWord] = []
        result.reserveCapacity(5000)
        var index = 0
        for line in text.split(separator: "\n", omittingEmptySubsequences: true) {
            let f = line.split(separator: "\t", omittingEmptySubsequences: false)
            guard f.count >= 5 else { continue }
            index += 1
            result.append(
                ChineseWord(
                    id: index,
                    japanese: String(f[0]),
                    chinese: String(f[1]),
                    pinyin: String(f[2]),
                    frequency: Int(f[3]) ?? 3,
                    examples: String(f[4])
                )
            )
        }
        return result
    }

    private static let raw = #"""
